using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// Options with the default reflection-based resolver (resolves any type)
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// 1️⃣ GetTypeInfo<T>() — returns strongly-typed JsonTypeInfo<T>
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person> → Type={personInfo.Type.Name}, Kind={personInfo.Kind}");

string json = JsonSerializer.Serialize(new Person("Alice", 42), personInfo);
Console.WriteLine($"Serialized: {json}");

// 2️⃣ TryGetTypeInfo<T>() — probe without throwing
// This succeeds because the default resolver can handle Person.
if (options.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? info))
{
    Console.WriteLine($"\nTryGetTypeInfo<Person> succeeded → {info!.Type.Name}");
}

// Now use a restricted resolver that only knows about Person.
// Attempting to resolve an unknown type (e.g. int[]) will NOT throw.
var restricted = new JsonSerializerOptions
{
    TypeInfoResolver = new PersonOnlyResolver()
};

if (restricted.TryGetTypeInfo<int[]>(out JsonTypeInfo<int[]>? arrayInfo))
{
    Console.WriteLine($"\nTryGetTypeInfo<int[]> succeeded → {arrayInfo!.Type.Name}");
}
else
{
    Console.WriteLine("\nTryGetTypeInfo<int[]> returned false — metadata not available (no exception thrown)");
}

// A minimal resolver that only provides metadata for Person.
class PersonOnlyResolver : IJsonTypeInfoResolver
{
    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options)
    {
        if (type == typeof(Person))
        {
            return JsonMetadataServices.CreateObjectInfo<Person>(options,
                new JsonObjectInfoValues<Person>());
        }
        return null; // unknown type
    }
}

public record Person(string Name, int Age);
